def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    templates = []
    for r in {0, h - 1}:
        row = grid[r]
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            seq = row[start:c]
            if len(seq) > 1:
                templates.append(seq)
    for r in range(1, h - 1):
        for c in range(w):
            value = grid[r][c]
            if value == 0:
                continue
            choices = [seq for seq in templates if value in seq]
            if not choices:
                continue
            seq = choices[0]
            anchor = seq.index(value)
            start = c - anchor
            for j, color in enumerate(seq):
                x = start + j
                if 0 <= x < w:
                    out[r][x] = color
    return out
